Cy_SysClk_IloStartMeasurement.text:
Cy_SysClk_IloStartMeasurement(void)
{
    if (!preventIloMeasurment)
    {
        iloMeasurment = true;

        /* Configure measurement counters to source by SysClk (Counter 1) and ILO (Counter 2)*/
        CY_REG32_CLR_SET(SRSSLT_CLK_DFT_SELECT,
                         SRSSLT_CLK_DFT_SELECT_DFT_SEL1,
                         SRSSLT_CLK_DFT_SELECT_DFT_SEL_ILO);

        CY_REG32_CLR_SET(SRSSLT_TST_DDFT_CTRL,
                         SRSSLT_TST_DDFT_CTRL_DFT_SEL,
               (_VAL2FLD(SRSSLT_TST_DDFT_CTRL_DFT_SEL0,
                         SRSSLT_TST_DDFT_CTRL_DFT_SEL_CLK0) |
                _VAL2FLD(SRSSLT_TST_DDFT_CTRL_DFT_SEL1,
                         SRSSLT_TST_DDFT_CTRL_DFT_SEL_CLK1)));
    }
}

Cy_SysClk_IloStopMeasurement.text:
Cy_SysClk_IloStopMeasurement(void)
{
    if (!preventIloMeasurment)
    {
        iloMeasurment = false;

        /* Set default configurations in 11...8 DFT register bits to zero */
        SRSSLT_CLK_DFT_SELECT &= ~SRSSLT_CLK_DFT_SELECT_DFT_SEL1_Msk;
        SRSSLT_TST_DDFT_CTRL &= SRSSLT_TST_DDFT_CTRL_DFT_SEL_Msk;
    }
}

Cy_SysClk_IloCompensate.text:
Cy_SysClk_IloCompensate() function.
*
* This function configures measurement counters to be sourced by SysClk (Counter 1)
* and ILO (Counter 2).
*
* \note SysClk should be clocked by IMO, otherwise
* Cy_SysClk_IloCompensate() function can give incorrect results.
*
* \funcusage
* \snippet sysclk/sut/sysclk_snippet.c SNIPPET_SYSCLK_ILO_COMPENSATE
* \snippet sysclk/sut/sysclk_snippet.c SNIPPET_SYSCLK_WDT_CFG
*
******************************************************************************/
void Cy_SysClk_IloStartMeasurement(void)
{
    if (!preventIloMeasurment)
    {
        iloMeasurment = true;

        /* Configure measurement counters to source by SysClk (Counter 1) and ILO (Counter 2)*/
        CY_REG32_CLR_SET(SRSSLT_CLK_DFT_SELECT,
                         SRSSLT_CLK_DFT_SELECT_DFT_SEL1,
                         SRSSLT_CLK_DFT_SELECT_DFT_SEL_ILO);

        CY_REG32_CLR_SET(SRSSLT_TST_DDFT_CTRL,
                         SRSSLT_TST_DDFT_CTRL_DFT_SEL,
               (_VAL2FLD(SRSSLT_TST_DDFT_CTRL_DFT_SEL0,
                         SRSSLT_TST_DDFT_CTRL_DFT_SEL_CLK0) |
                _VAL2FLD(SRSSLT_TST_DDFT_CTRL_DFT_SEL1,
                         SRSSLT_TST_DDFT_CTRL_DFT_SEL_CLK1)));
    }
}

Cy_SysPm_ExecuteCallback.text:
Cy_SysPm_ExecuteCallback(cy_en_syspm_callback_type_t type, cy_en_syspm_callback_mode_t mode)
{
    CY_ASSERT_L3(CY_SYSPM_IS_CALLBACK_TYPE_VALID(type));
    CY_ASSERT_L3(CY_SYSPM_IS_CALLBACK_MODE_VALID(mode));

    static cy_stc_syspm_callback_t* lastExecutedCallback = NULL;
    cy_en_syspm_status_t retVal = CY_SYSPM_SUCCESS;
    cy_stc_syspm_callback_t* curCallback = pmCallbackRoot[(uint32_t) type];
    cy_stc_syspm_callback_params_t curParams;

    if ((mode == CY_SYSPM_BEFORE_TRANSITION) || (mode == CY_SYSPM_CHECK_READY))
    {
        /* Execute registered callbacks with order from first registered to the
        *  last registered. Stop executing if CY_SYSPM_FAIL was returned in
        *  CY_SYSPM_CHECK_READY mode
        */
        while ((curCallback != NULL) && ((retVal != CY_SYSPM_FAIL) || (mode != CY_SYSPM_CHECK_READY)))
        {
            /* The modes defined in the .skipMode element are not executed */
            if (0UL == ((uint32_t) mode & curCallback->skipMode))
            {
                /* Update elements for local callback parameter values */
                curParams.base = curCallback->callbackParams->base;
                curParams.context = curCallback->callbackParams->context;

                retVal = curCallback->callback(&curParams, mode);

                /* Update callback pointer with value of executed callback.
                * Such update is required to execute further callbacks in
                * backward order after exit from LP mode or to undo
                * configuration after callback returned fail: from last called
                * to first registered.
                */
                lastExecutedCallback = curCallback;
            }
            curCallback = curCallback->nextItm;
        }

        if (mode == CY_SYSPM_CHECK_READY)
        {
            /* Update the pointer to  the failed callback with the result of the callback execution.
            *  If the callback fails, the value of the pointer will be updated
            *  with the address of the callback which returned CY_SYSPM_FAIL, else,
            *  it will be updated with NULL.
            */
            if(retVal == CY_SYSPM_FAIL)
            {
                failedCallback[(uint32_t) type] = lastExecutedCallback;
            }
            else
            {
                failedCallback[(uint32_t) type] = NULL;
            }
        }
    }
    else
    {
        /* Execute registered callbacks with order from lastCallback or last
        * executed to the first registered callback. Such a flow is required if
        * a previous callback function returned CY_SYSPM_FAIL or a previous
        * callback mode was CY_SYSPM_BEFORE_TRANSITION. Such an order is
        * required to undo configurations in correct backward order.
        */
        if (mode != CY_SYSPM_CHECK_FAIL)
        {
            while (curCallback->nextItm != NULL)
            {
                curCallback = curCallback->nextItm;
            }
        }
        else
        {
            /* Skip last executed callback that returns CY_SYSPM_FAIL, as this
            *  callback already knows that it failed.
            */
            curCallback = lastExecutedCallback;

            if (curCallback != NULL)
            {
                curCallback = curCallback->prevItm;
            }
        }

        /* Execute callback functions with required type and mode */
        while (curCallback != NULL)
        {
            /* The modes defined in the .skipMode element are not executed */
            if (0UL == ((uint32_t) mode & curCallback->skipMode))
            {
                /* Update elements for local callback parameter values */
                curParams.base = curCallback->callbackParams->base;
                curParams.context = curCallback->callbackParams->context;

                retVal = curCallback->callback(&curParams, mode);
            }
            curCallback = curCallback->prevItm;
        }
    }

    return retVal;
}

ProcessStatusCode.text:
ProcessStatusCode(void)
{
    cy_en_flashdrv_status_t result;
    uint32_t statuscode = CPUSS_SYSARG;

    if ((statuscode & SROMCODE_STATUS_MASK) == SROMCODE_SUCCESS)
    {
        result = CY_FLASH_DRV_SUCCESS;
    }
    else if ((statuscode & SROMCODE_STATUS_MASK) == SROMCODE_ERROR_FLAG)
    {
        /* Process error code */
        switch (statuscode)
        {
            case SROMCODE_INVALID_PROTECTION:
            {
                result = CY_FLASH_DRV_INVALID_PROT;
                break;
            }
            case SROMCODE_INVALID_FM_PL:
            case SROMCODE_INVALID_FLASH_ADDR:
            {
                result = CY_FLASH_DRV_INVALID_FLASH_ADDR;
                break;
            }
            case SROMCODE_ROW_PROTECTED:
            {
                result = CY_FLASH_DRV_ROW_PROTECTED;
                break;
            }
            case SROMCODE_RESUME_COMPLETE:
            {
                result = CY_FLASH_DRV_SUCCESS;
                break;
            }
            case SROMCODE_PENDING_RESUME:
            {
                result = CY_FLASH_DRV_PENDING_RESUME;
                break;
            }
            case SROMCODE_SYSCALL_IN_PROGRESS:
            {
                result = CY_FLASH_DRV_PROGRESS_NO_ERROR;
                break;
            }
            case SROMCODE_API_NOT_INSTANTIATED:
            case SROMCODE_INVALID_FLASH_IP:
            case SROMCODE_NA_IN_DEAD_MODE:
            {
                result = CY_FLASH_DRV_DEV_NOT_SUPPORTED;
                break;
            }
            default:
            {
                result = CY_FLASH_DRV_ERROR_UNKNOWN;
                break;
            }
        }
    }
    else
    {
        /* Not an error or success - the operation in not finished */
        result = CY_FLASH_DRV_OPERATION_STARTED;
    }

    return (result);
}

Cy_Flash_ClockBackup.text:
Cy_Flash_ClockBackup(void)
{
    cy_en_flashdrv_status_t result = CY_FLASH_DRV_SUCCESS;
    volatile uint32_t   parameters[2U];

    parameters[0U] =(uint32_t) ((CY_FLASH_KEY_TWO(CY_FLASH_API_OPCODE_CLK_BACKUP) <<  CY_FLASH_PARAM_KEY_TWO_OFFSET) |
                            CY_FLASH_KEY_ONE);
    parameters[1U] = (uint32_t) &cySysFlashBackup.clockSettings[0U];
    CPUSS_SYSARG = (uint32_t) &parameters[0U];
    CPUSS_SYSREQ = CY_FLASH_CPUSS_REQ_START | CY_FLASH_API_OPCODE_CLK_BACKUP;
    __NOP();
    result = ProcessStatusCode();

    /* Enabling IMO after backup completion as required by hardware.
    *  The Cy_Flash_ClockRestore() restores original state of the system.
    */
    Cy_SysClk_ImoEnable();

    return (result);
}

Cy_Flash_ClockConfig.text:
Cy_Flash_ClockConfig(void)
{
    cy_en_flashdrv_status_t result = CY_FLASH_DRV_SUCCESS;
#if defined(CY_IP_M0S8SRSSHV)
    Cy_SysClk_UnlockProtReg();
#endif /* defined(CY_IP_M0S8SRSSHV) */
    /* FM-Lite Clock Configuration */
    CPUSS_SYSARG =(uint32_t) ((CY_FLASH_KEY_TWO(CY_FLASH_API_OPCODE_CLK_CONFIG) <<  CY_FLASH_PARAM_KEY_TWO_OFFSET) |
                    CY_FLASH_KEY_ONE);
    CPUSS_SYSREQ = CY_FLASH_CPUSS_REQ_START | CY_FLASH_API_OPCODE_CLK_CONFIG;
    __NOP();
    result = ProcessStatusCode();
#if defined(CY_IP_M0S8SRSSHV)
    Cy_SysClk_LockProtReg();
#endif /* defined(CY_IP_M0S8SRSSHV) */
    return (result);
}

Cy_Flash_ClockRestore.text:
Cy_Flash_ClockRestore(void)
{
    cy_en_flashdrv_status_t result = CY_FLASH_DRV_SUCCESS;
    volatile uint32_t   parameters[2U];
#if defined(CY_IP_M0S8SRSSHV)
    Cy_SysClk_UnlockProtReg();
#endif /* defined(CY_IP_M0S8SRSSHV) */
    /* FM-Lite Clock Restore */
    parameters[0U] = (uint32_t) ((CY_FLASH_KEY_TWO(CY_FLASH_API_OPCODE_CLK_RESTORE) <<  CY_FLASH_PARAM_KEY_TWO_OFFSET) |
                    CY_FLASH_KEY_ONE);
    parameters[1U] = (uint32_t) &cySysFlashBackup.clockSettings[0U];
    CPUSS_SYSARG = (uint32_t) &parameters[0U];
    CPUSS_SYSREQ = CY_FLASH_CPUSS_REQ_START | CY_FLASH_API_OPCODE_CLK_RESTORE;

    __NOP();
    result = ProcessStatusCode();
#if defined(CY_IP_M0S8SRSSHV)
    Cy_SysClk_LockProtReg();
#endif /* defined(CY_IP_M0S8SRSSHV) */
    return (result);
}

Cy_Flash_WriteRow.text:
Cy_Flash_WriteRow(uint32_t rowAddr, const uint32_t* data)
{
    cy_en_flashdrv_status_t result = CY_FLASH_DRV_DEV_NOT_SUPPORTED;

    volatile uint32_t parameters[(CY_FLASH_SIZEOF_ROW + CY_FLASH_SRAM_ROM_DATA) / sizeof(uint32_t)];
    uint32_t interruptState;
    uint32_t rowNum = Cy_Flash_GetRowNum(rowAddr);

    if ((Cy_Flash_ValidAddr(rowAddr)) && (NULL != data))
    {
        /* Copy data to be written into internal variable */
        (void) memcpy((void *) &parameters[2U], (const void *) data, CY_FLASH_SIZEOF_ROW);

        parameters[0U] = (uint32_t) (CY_FLASH_GET_MACRO_FROM_ROW(rowNum)        << CY_FLASH_PARAM_MACRO_SEL_OFFSET) |
                         (uint32_t) (CY_FLASH_PAGE_LATCH_START_ADDR             << CY_FLASH_PARAM_ADDR_OFFSET     ) |
                         (uint32_t) (CY_FLASH_KEY_TWO(CY_FLASH_API_OPCODE_LOAD) << CY_FLASH_PARAM_KEY_TWO_OFFSET  ) |
                         CY_FLASH_KEY_ONE;
        parameters[1U] = CY_FLASH_SIZEOF_ROW - 1U;

        CPUSS_SYSARG = (uint32_t) &parameters[0U];
        CPUSS_SYSREQ = CY_FLASH_CPUSS_REQ_START | CY_FLASH_API_OPCODE_LOAD;
        __NOP();

        result = ProcessStatusCode();
        if(CY_FLASH_DRV_SUCCESS == result)
        {
            interruptState = Cy_SysLib_EnterCriticalSection();
            result = Cy_Flash_ClockBackup();
            if (CY_FLASH_DRV_SUCCESS == result)
            {
                result = Cy_Flash_ClockConfig();
                if (CY_FLASH_DRV_SUCCESS == result)
                {
                    cy_en_flashdrv_status_t resultClockRestore;

                    /* Write Row */
                    CPUSS_SYSARG = (uint32_t) &parameters[0U];
                    if (rowAddr >= CY_SFLASH_BASE)
                    {
                        /* Supervisory Flash */
                        parameters[0U] = (uint32_t) (((uint32_t) CY_FLASH_KEY_TWO(CY_FLASH_API_OPCODE_WRITE_SFLASH_ROW) <<  CY_FLASH_PARAM_KEY_TWO_OFFSET) | CY_FLASH_KEY_ONE);
                        parameters[1U] = (uint32_t) rowNum;
                        CPUSS_SYSREQ = CY_FLASH_CPUSS_REQ_START | CY_FLASH_API_OPCODE_WRITE_SFLASH_ROW;
                    }
                    else
                    {
                        /* Flash */
                        parameters[0U]  = (uint32_t) (((uint32_t) CY_FLASH_KEY_TWO(CY_FLASH_API_OPCODE_WRITE_ROW) <<  CY_FLASH_PARAM_KEY_TWO_OFFSET) | CY_FLASH_KEY_ONE);
                        parameters[0U] |= (uint32_t)(rowNum << 16U);
                        CPUSS_SYSREQ = CY_FLASH_CPUSS_REQ_START | CY_FLASH_API_OPCODE_WRITE_ROW;
                    }
                    __NOP();

                    result = ProcessStatusCode();
                    resultClockRestore = Cy_Flash_ClockRestore();
                    if (CY_FLASH_DRV_SUCCESS == result)
                    {
                        result = resultClockRestore;
                    }
#if defined(CPUSS_SPCIF_FLASH_S8FS_VER2)
                    /*
                     * if the whole flash macro cell is locked, the return code from SROM is UNKNOWN
                     */
                    else
                    {
                        /*
                         * Check if the macro cell is protected
                         * 1 - unprotected
                         * 0 - protected
                         */
                        uint32_t protection;
                        uint32_t macroNum;
                        /* It is safe to suppress return code as the pointer is always valid */
                        (void)Cy_Flash_GetProtectionStatus(&protection);
                        macroNum = Cy_Flash_GetMacroNumFromRowNum(rowNum);
                        /*
                         * macroNum bit into the protection represent state
                         * of the macroNum flash macro cell
                         */
                        if(0U == CY_CHECK_BIT(protection,macroNum))
                        {
                            /* If the macro is protected, replace the error code by more readable */
                            result = CY_FLASH_DRV_ROW_PROTECTED;
                        }
                    }
#endif /* defined(CPUSS_SPCIF_FLASH_S8FS_VER2) */
                }
            }
            Cy_SysLib_ExitCriticalSection(interruptState);
        }
    }
    return (result);
}

